SELECT f.follower_id FROM user_follow f WHERE f.following_id = :id AND NOT ((EXISTS (SELECT 1 FROM user_block hsb WHERE hsb.blocker_id = f.follower_id AND hsb.blocked_id = :id) OR EXISTS (SELECT 1 FROM user_mute hsm WHERE hsm.user_id = f.follower_id AND hsm.muted_user_id = :id AND hsm.hide_notifications AND (hsm.expires_at IS NULL OR hsm.expires_at > :now))) OR EXISTS (SELECT 1 FROM user_block hab WHERE hab.blocker_id = :id AND hab.blocked_id = f.follower_id))
SELECT f.follower_id FROM user_follow f WHERE f.following_id = :id AND f.notify_notes AND NOT ((EXISTS (SELECT 1 FROM user_block hsb WHERE hsb.blocker_id = f.follower_id AND hsb.blocked_id = :id) OR EXISTS (SELECT 1 FROM user_mute hsm WHERE hsm.user_id = f.follower_id AND hsm.muted_user_id = :id AND hsm.hide_notifications AND (hsm.expires_at IS NULL OR hsm.expires_at > :now))) OR EXISTS (SELECT 1 FROM user_block hab WHERE hab.blocker_id = :id AND hab.blocked_id = f.follower_id))
SELECT s.user_id FROM (SELECT r.user_id FROM note_repost r WHERE r.note_id = :note UNION SELECT q.user_id FROM note q WHERE q.quoted_note_id = :note AND q.user_id IS NOT NULL) s JOIN note n ON n.id = :note WHERE NOT EXISTS (SELECT 1 FROM note_conversation_mute c WHERE c.user_id = s.user_id AND c.conversation_id = COALESCE(n.conversation_id, n.id)) AND s.user_id <> :author AND NOT ((EXISTS (SELECT 1 FROM user_block hsb WHERE hsb.blocker_id = s.user_id AND hsb.blocked_id = :author) OR EXISTS (SELECT 1 FROM user_mute hsm WHERE hsm.user_id = s.user_id AND hsm.muted_user_id = :author AND hsm.hide_notifications AND (hsm.expires_at IS NULL OR hsm.expires_at > :now))) OR EXISTS (SELECT 1 FROM user_block hab WHERE hab.blocker_id = :author AND hab.blocked_id = s.user_id))
SELECT s.user_id FROM (SELECT r.user_id FROM note_repost r WHERE r.note_id = :note UNION SELECT q.user_id FROM note q WHERE q.quoted_note_id = :note AND q.user_id IS NOT NULL) s JOIN note n ON n.id = :note WHERE NOT EXISTS (SELECT 1 FROM note_conversation_mute c WHERE c.user_id = s.user_id AND c.conversation_id = COALESCE(n.conversation_id, n.id)) AND NOT EXISTS (SELECT 1 FROM user_domain_block d JOIN federation_remote_actor a ON a.domain = d.domain WHERE d.user_id = s.user_id AND a.id = :remote) AND NOT (EXISTS (SELECT 1 FROM federation_remote_block hrb WHERE hrb.user_id = s.user_id AND hrb.remote_actor_id = :remote) OR EXISTS (SELECT 1 FROM federation_remote_mute hrn WHERE hrn.user_id = s.user_id AND hrn.remote_actor_id = :remote AND hrn.hide_notifications AND (hrn.expires_at IS NULL OR hrn.expires_at > :now)))
